const kst=t=>t?new Intl.DateTimeFormat('ko-KR',{timeZone:'Asia/Seoul',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(t)):'수집 시각 미상';
const dayAdd=(s,n)=>new Date(Date.parse(s+'T00:00:00Z')+n*86400000).toISOString().slice(0,10);
const weekStart=s=>dayAdd(s,-((new Date(s+'T00:00:00Z').getUTCDay()+6)%7));
const ch=id=>CHANNELS.find(c=>c.id===id);
const badge=c=>`<span class="channelbadge" style="--color:${c.color};--tint:${c.tint}">${c.icon}</span>`;
const sum=(rows,key)=>rows.reduce((s,r)=>s+(Number.isFinite(r[key])?r[key]:0),0);
const safeUrl=u=>{try{const p=new URL(u,location.href);return /^(https?:)$/.test(p.protocol)?p.href:'#'}catch{return '#'}};
let period='all',selected='all',pageNum=1,query='',sortBy='views';
let savedGoals={};try{savedGoals=JSON.parse(localStorage.getItem('pulse-real-goals-v1')||'{}')||{}}catch{}
const thisWeek=weekStart(DATA.asOfDate),endWeek=dayAdd(thisWeek,6);
const style=document.createElement('style');style.textContent=`.realbadge{background:#e5f5ed;color:#177b53;padding:6px 9px;border-radius:5px;font-size:10px;font-weight:700}.status{line-height:1.7}.data-alert{border-left:3px solid #d79a3e;background:#fff8ed;color:#876028;padding:14px 18px;font-size:11px;line-height:1.85;border-radius:8px;margin:18px 0}.channelperiod{font-size:10px;color:#84909f;line-height:1.7;margin-top:8px;min-height:34px}.channelinsight{min-height:44px}.goal .big{font-size:30px;letter-spacing:-1px}.coverage-row{font-size:11px;line-height:1.9;border-bottom:1px solid #edf0f4;padding:10px 0}.coverage-row:last-child{border:0}.coverage-row b{color:#354156}.data-period{font-size:10px;color:#8893a2;max-width:240px;white-space:normal;line-height:1.8}.metric-sub{display:block;font-size:9px;color:#94a0ae;font-weight:400;margin-top:5px}.extra-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.extra-stat{background:#f6f8fc;border-radius:7px;padding:10px;font-size:10px;color:#7a8798;line-height:1.6}.extra-stat strong{display:block;font-size:15px;color:#344054;margin-top:4px}.source-link{color:#596bd0;text-decoration:underline;text-underline-offset:3px}.summary-label{margin:12px 0 3px;font-size:10px;color:#8691a0}.contenttitle{max-width:300px}.real-thumb{width:72px;height:48px;object-fit:cover;border-radius:6px;flex:none;background:#eff2f6}.no-thumb{width:72px;height:48px;display:grid;place-items:center;border-radius:6px;background:#f0f3f7;color:#8b95a6;font-size:9px;flex:none}.content-open{border:0;background:none;text-align:left;padding:0;color:inherit}.content-open:hover .contenttitle{color:#4d62e8}.n-a{font-size:10px;color:#98a2b1}.preview-dialog{max-width:760px;width:760px}.detail-head{display:flex;justify-content:space-between;align-items:center;gap:20px}.detail-head h2{font-size:18px}.detail-img{max-width:100%;max-height:370px;display:block;object-fit:contain;margin:14px auto}.detail-table td{padding:9px 12px;font-size:11px;white-space:normal}.detail-table td:first-child{color:#8390a1;width:42%}.detail-table td:last-child{overflow-wrap:anywhere}.empty-chart{padding:45px 15px;color:#8b96a5;font-size:12px;text-align:center}.goalright strong{font-size:20px}.mini-note{font-size:10px;color:#8492a5;line-height:1.85}.linechart circle{stroke:white;stroke-width:1}.source-note{font-size:10px;color:#8b96a5;line-height:1.85;margin-top:12px}.footer{line-height:1.8}.actions{flex-wrap:wrap}.muted{color:#8e99a8}.detail-json{white-space:pre-wrap;font-size:10px;line-height:1.7;max-height:280px;overflow:auto;background:#f5f7fb;padding:12px;border-radius:7px;overflow-wrap:anywhere}.chartday{font-size:8px;fill:#9aa3af}@media(max-width:650px){.extra-grid{grid-template-columns:1fr 1fr}.topbar{height:auto;min-height:80px;gap:10px;flex-wrap:wrap;padding:14px 0}.topright{flex-wrap:wrap;gap:7px}.heading .actions{justify-content:flex-start}.sectionhead{flex-wrap:wrap}.data-period{max-width:175px}.goal .big{font-size:25px}}`;
document.head.appendChild(style);
function sourceLink(url,text='출처 보기'){return `<a class="source-link" href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>`}
function startDate(){return period==='all'?DATA.chartStart:dayAdd(DATA.asOfDate,1-Number(period))}
function channelRows(){return DATA.channels.filter(c=>selected==='all'||c.id===selected)}
function contentRows(){return DATA.content.filter(p=>(selected==='all'||p.channel===selected)&&(period==='all'||(p.published_date_kst&&p.published_date_kst>=startDate()&&p.published_date_kst<=DATA.asOfDate))&&(!query||(p.title+' '+ch(p.channel).name+' '+p.post_id).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>{const av=a[sortBy],bv=b[sortBy];if(av==null&&bv==null)return 0;if(av==null)return 1;if(bv==null)return-1;return bv-av})}
function chart(){const start=startDate(),days=[];for(let d=start;d<=DATA.asOfDate;d=dayAdd(d,1))days.push(d);const series=CHANNELS.filter(c=>selected==='all'||c.id===selected).map(c=>({c,rows:DATA.daily.filter(r=>r.channel===c.id&&r.date>=start&&r.date<=DATA.asOfDate)})).filter(s=>s.rows.length);if(!series.length)return '<div class="empty-chart">선택 채널의 일별 활동 데이터가 없습니다.<br>누적 조회수로 일별 실적을 만들지 않습니다.</div>';const top=Math.max(1,...series.flatMap(s=>s.rows.map(r=>r.views)));const x=i=>35+i*555/(days.length-1||1),y=v=>151-v/top*136;let svg='<svg viewBox="0 0 600 176" class="linechart" role="img" aria-label="원본 보고 날짜별 조회수. 미제공 날짜는 선을 잇지 않습니다.">';for(let i=0;i<4;i++){const val=top*(3-i)/3;svg+=`<line x1="35" y1="${y(val)}" x2="590" y2="${y(val)}" stroke="#e9edf3" stroke-dasharray="3 3"/><text x="28" y="${y(val)+3}" text-anchor="end" class="chartday">${Math.round(val)}</text>`}for(const {c,rows} of series){let segment=[];const emit=()=>{if(segment.length>1)svg+=`<polyline points="${segment.join(' ')}" fill="none" stroke="${c.color}" stroke-width="2"/>`;segment=[]};for(let i=0;i<days.length;i++){const r=rows.find(r=>r.date===days[i]);if(!r||r.views===null){emit();continue}segment.push(`${x(i)},${y(r.views)}`);svg+=`<circle cx="${x(i)}" cy="${y(r.views)}" r="2.8" fill="${c.color}"><title>${esc(c.name+' '+r.date+' '+r.views+'회')}</title></circle>`}emit()}return svg+'</svg><div class="chartlabels"><span>'+start+'</span><span>'+DATA.asOfDate+'</span></div>'}
function render(){const rows=contentRows(),pageCount=Math.max(1,Math.ceil(rows.length/8));pageNum=Math.min(pageNum,pageCount);const visible=rows.slice((pageNum-1)*8,pageNum*8),goal=savedGoals[thisWeek];document.getElementById('body').innerHTML=`<div class="heading"><div><div class="eyebrow">REAL CHANNEL SNAPSHOT</div><h1>성과 대시보드</h1><p class="subtitle">실제 계정 데이터로 교체했습니다. 원본 기간과 수집 시각을 함께 확인하세요.</p></div><div class="actions"><button class="btn" id="exportJson">전체 JSON</button><button class="btn" id="exportAll">전체 CSV</button></div></div>
<section class="card goal" aria-label="이번 주 KPI"><div><div class="goalhead"><span class="label">이번 주 핵심 목표</span><span class="label">${thisWeek.slice(5)} ~ ${endWeek.slice(5)}</span></div><h2>4개 채널 합산 주간 조회수 <span class="pill">집계 보류</span></h2><div class="goalnums"><span class="big">합산 데이터 없음</span><span class="target">${goal?'/ 목표 '+fmt(goal)+'회':''}</span></div><p class="mini-note">기간·시간대·집계 정의가 다르고 Instagram·X의 일별 활동이 없습니다.<br>누적 조회수를 합쳐 주간 달성률을 만들지 않습니다.</p></div><div class="goalright"><h3>가상 목표·달성률·성장 추천 제거</h3><strong>${goal?'직접 설정한 목표 '+fmt(goal)+'회':'실제 데이터 기준으로 다시 시작'}</strong><p>직전 4주 동일 기준의 실제 자료가 없어 자동 추천은 제공하지 않습니다.<br>기존 데모 목표 저장값도 불러오지 않습니다.</p><button class="btn small" id="openGoal">이번 주 목표 입력 / 수정</button></div></section>
<div class="sectionhead"><div><h2>채널 인사이트</h2><p>최신 관찰값 · 아래 4개 카드는 서로 다른 원본 보고 기간입니다. 합계·기여율은 표시하지 않습니다.</p></div>${selected!=='all'?'<button class="btn small" id="clearChannel">전체 채널 보기</button>':''}</div>
<div class="channels">${DATA.channels.map(s=>{const c=ch(s.id);return `<button class="card channel ${selected===c.id?'selected':''}" data-channel="${c.id}" aria-pressed="${selected===c.id}"><div class="channelname">${badge(c)}${c.name}</div><div class="channelvalue">${fmt(s.value)}<span style="font-size:11px;color:#8c97a6;margin-left:6px">${esc(s.metricLabel)}</span></div><div class="channelperiod">${esc(s.periodLabel)}</div><div class="channelinsight">${esc(s.secondary)}<br>${c.id==='youtube'?'구독자':'팔로워'} <b>${fmt(s.followers)}</b>명 · 콘텐츠 <b>${s.contentCount}</b>개</div><div class="channelmeta">${kst(s.collectedAt)} KST 수집 · 수동 스냅샷</div></button>`}).join('')}</div>
<div class="data-alert"><b>숫자 해석에 주의하세요.</b> YouTube·Meta 조회수와 X 게시물 노출수는 같은 지표가 아닙니다. 콘텐츠 누적값과 날짜별 발생값을 분리했습니다. ${esc(DATA.facebookIdentity.note)}<br>자동 API 동기화가 아닌 수집 스냅샷이며, 확인되지 않은 항목은 <b>데이터 없음</b>으로 표시합니다.</div>
<div class="sectionhead"><div><h2>일별 활동 / 게시일 필터</h2><p>${startDate()} ~ ${DATA.asOfDate} · 일별 차트와 KST 게시일에만 적용 · Facebook 게시일 미확정 항목은 기간 선택 시 제외</p></div><div class="segments" aria-label="분석 기간">${[1,7,30,'all'].map(p=>`<button data-period="${p}" class="${period===p?'active':''}" aria-pressed="${period===p}">${p==='all'?'전체':p+'일'}</button>`).join('')}</div></div>
<div class="analysisrow"><section class="card chartcard"><div class="cardtitle"><h3>조회수 추이 · 원본 보고 날짜</h3><div class="legend">${CHANNELS.filter(c=>(selected==='all'||c.id===selected)&&DATA.daily.some(r=>r.channel===c.id)).map(c=>`<span><i class="dot" style="background:${c.color}"></i>${c.name}</span>`).join('')}</div></div>${chart()}<p class="source-note">${DATA.dailyNotes.map(esc).join('<br>')}<br>Instagram·X 일별값 없음. 차트의 빈 날짜는 0이 아니라 미제공입니다.</p><button class="btn small" id="exportDaily">일별 CSV</button></section><section class="card chartcard"><div class="cardtitle"><h3>데이터 수집 상태</h3><small>실제 원자료</small></div>${channelRows().map(s=>`<div class="coverage-row"><b>${esc(ch(s.id).name)}</b> · ${esc(s.account)}<br>${esc(s.coverage)}<br>${sourceLink(s.sourceUrl)} · ${kst(s.collectedAt)} KST</div>`).join('')}</section></div>
<div class="sectionhead"><div><h2>지표별 성과</h2><p>팔로워는 현재 관찰 스냅샷, 콘텐츠 수는 확보한 고유 항목 수입니다. 조회 기간은 행마다 다릅니다.</p></div><button class="btn small" id="exportMetrics">지표 CSV</button></div>
<section class="card tablewrap"><table><thead><tr><th>채널</th><th class="num">팔로워 / 구독자</th><th class="num">확보 콘텐츠</th><th class="num">원본 조회 / 노출</th><th>지표·기간</th><th>반응·추가 지표</th></tr></thead><tbody>${channelRows().map(s=>`<tr><td><span class="tablename">${badge(ch(s.id))}${esc(ch(s.id).name)}</span></td><td class="num">${fmt(s.followers)}</td><td class="num">${s.contentCount}</td><td class="num">${fmt(s.value)}</td><td class="data-period">${esc(s.metricLabel)}<br>${esc(s.periodLabel)}</td><td class="data-period">${esc(s.extraLabel)}</td></tr>`).join('')}</tbody></table><div class="tablefoot">전환수 열은 제거했습니다. 기존 전환수는 구매·리드 전환이 아닌 반응 합계였습니다. 좋아요·저장·공유·재게시·댓글은 콘텐츠 상세에 각각 표시합니다. Facebook 참여는 클릭도 포함하며 공감과 다릅니다. 기간·정의가 다른 값의 전체 합계는 제공하지 않습니다.</div></section>
<div class="sectionhead"><div><h2>콘텐츠별 인사이트 <span class="muted" style="font-size:11px">${rows.length}개</span></h2><p>채널별 누적 / 개별 인사이트 스냅샷. 게시일 필터가 조회수 발생 기간을 뜻하지는 않습니다.</p></div><div class="actions"><input class="search" id="search" aria-label="콘텐츠 검색" placeholder="콘텐츠 검색" value="${esc(query)}"><select class="filterselect" id="sort" aria-label="콘텐츠 정렬"><option value="views" ${sortBy==='views'?'selected':''}>조회·노출 높은 순</option><option value="comments" ${sortBy==='comments'?'selected':''}>댓글 높은 순</option></select><button class="btn small" id="exportContent">콘텐츠 CSV</button></div></div>
<section class="card tablewrap"><table><thead><tr><th>#</th><th>콘텐츠</th><th>채널</th><th>게시일</th><th class="num">누적 조회 / 노출</th><th class="num">확인 반응</th><th class="num">댓글</th></tr></thead><tbody>${visible.map((p,i)=>`<tr><td class="rank">${(pageNum-1)*8+i+1}</td><td><button class="content-open" data-open="${esc(p.channel+':'+p.post_id)}" aria-label="${esc(p.title||'제목 없는 사진')} 상세 보기"><span class="tablename">${p.thumbnail_url?`<img class="real-thumb" src="${esc(safeUrl(p.thumbnail_url))}" alt="${esc(p.title)} 실제 썸네일" loading="lazy" referrerpolicy="no-referrer">`:'<span class="no-thumb">원본 링크</span>'}<span><span class="contenttitle" style="display:block">${esc(p.title||'제목 없는 사진')}</span><span class="contentsub">${esc(p.type)} · ${esc(p.post_id)}</span></span></span></button></td><td style="color:${ch(p.channel).color}">${esc(ch(p.channel).name)}</td><td class="data-period">${esc(p.published_date_kst||p.published_date_raw||'미확인')}<span class="metric-sub">${p.published_date_kst?'KST':'원문 · KST 미확인'}</span></td><td class="num">${fmt(p.views)}<span class="metric-sub">${p.channel==='x'?'게시물 노출':p.views===null?'미제공':p.views_scope==='individual_insights_period_unspecified'?'기간 미표시 인사이트':'누적 스냅샷'}</span></td><td class="num">${fmt(p.known_reactions_sum)}<span class="metric-sub">${p.reactions_complete?'확인한 적용 항목':'확인 항목만 · 불완전'}</span></td><td class="num">${fmt(p.comments)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">해당 게시일·채널·검색 조건의 콘텐츠가 없습니다.</div>'}<div class="pagination"><span>확보 ${DATA.content.length}개 · channel + post_id 중복 제거 · 조회 미제공 ${DATA.content.filter(p=>p.views===null).length}개</span><div class="actions"><button class="btn small" id="prev" ${pageNum<=1?'disabled':''}>이전</button><span>${pageNum} / ${pageCount}</span><button class="btn small" id="next" ${pageNum>=pageCount?'disabled':''}>다음</button></div></div></section>
<div class="note">데이터 기준 ${DATA.asOfDate} · 최근 수집 ${kst(DATA.refreshedAt)} KST · 실시간 연결 아님.<br>${esc(DATA.publicationNote)}<br>JSON·CSV에는 실제 관찰값과 출처·범위를 저장합니다. 전체 CSV의 channel/content/daily행은 별도 집계 단위이므로 서로 더하면 중복됩니다.</div>`;
for(const b of document.querySelectorAll('[data-channel]'))b.onclick=()=>{selected=selected===b.dataset.channel?'all':b.dataset.channel;pageNum=1;render()};for(const b of document.querySelectorAll('[data-period]'))b.onclick=()=>{period=b.dataset.period==='all'?'all':Number(b.dataset.period);pageNum=1;render()};document.getElementById('clearChannel')?.addEventListener('click',()=>{selected='all';pageNum=1;render()});document.getElementById('search').oninput=e=>{query=e.target.value;const cursor=e.target.selectionStart;pageNum=1;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(cursor,cursor)};document.getElementById('sort').onchange=e=>{sortBy=e.target.value;pageNum=1;render()};document.getElementById('prev').onclick=()=>{pageNum--;render()};document.getElementById('next').onclick=()=>{pageNum++;render()};document.getElementById('exportJson').onclick=()=>download('social_pulse_real_'+DATA.asOfDate+'.json',JSON.stringify(DATA,null,2),'application/json');document.getElementById('exportAll').onclick=()=>exportCSV('social_pulse_real_all_'+DATA.asOfDate+'.csv',[...DATA.channels.map(r=>({record_type:'channel',...r})),...DATA.content.map(r=>({record_type:'content',...r})),...DATA.daily.map(r=>({record_type:'daily',...r}))]);document.getElementById('exportDaily').onclick=()=>exportCSV('daily_real_'+startDate()+'_'+DATA.asOfDate+'.csv',DATA.daily.filter(r=>(selected==='all'||r.channel===selected)&&r.date>=startDate()));document.getElementById('exportMetrics').onclick=()=>exportCSV('channels_real_'+DATA.asOfDate+'.csv',channelRows());document.getElementById('exportContent').onclick=()=>exportCSV('content_real_'+DATA.asOfDate+'.csv',rows);document.getElementById('openGoal').onclick=()=>{document.getElementById('goalInput').value=savedGoals[thisWeek]||'';document.getElementById('goalDialog').showModal()};for(const b of document.querySelectorAll('[data-open]'))b.onclick=()=>openContent(b.dataset.open);
}
function download(name,text,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(name,rows){const headers=[...new Set(['data_type',...rows.flatMap(r=>Object.keys(r))])];const quote=v=>'"'+String(v==null?'':typeof v==='object'?JSON.stringify(v):v).replaceAll('"','""')+'"';download(name,'\ufeff'+[headers,...rows.map(r=>headers.map(h=>h==='data_type'?'REAL_OBSERVED':r[h]))].map(r=>r.map(quote).join(',')).join('\r\n'))}
function openContent(key){const p=DATA.content.find(p=>p.channel+':'+p.post_id===key);if(!p)return;const metrics=[['조회 / 노출',fmt(p.views)],['좋아요 / 공감',fmt(p.likes)],['저장 / 북마크',fmt(p.saves)],['공유',fmt(p.shares)],['재게시',fmt(p.reposts)],['댓글',fmt(p.comments)],['확인 반응 합계',fmt(p.known_reactions_sum)+(p.reactions_complete?' (확인 항목)':' (전체 합계 아님)')],['조회 범위',p.views_scope],['공개 게시일 KST',p.published_date_kst||'미확인'],['원본 게시일 표기',p.published_date_raw],['데이터 수집',kst(p.collected_at)+' KST']];document.getElementById('detailBody').innerHTML=`<div class="detail-head"><div><div class="eyebrow">${esc(ch(p.channel).name)} · ${esc(p.type)}</div><h2>${esc(p.title||'제목 없는 사진')}</h2></div><button class="btn small" id="closeDetail">닫기</button></div>${p.thumbnail_url?`<img class="detail-img" src="${esc(safeUrl(p.thumbnail_url))}" alt="실제 콘텐츠 썸네일" referrerpolicy="no-referrer">`:''}<p class="mini-note">${sourceLink(p.source_url,'원본 콘텐츠 열기')} · ${esc(p.post_id)}<br>누락값은 0이 아닙니다. 동영상 재생수와 게시물 노출수, 기간값과 누적값은 서로 다릅니다.</p><table class="detail-table"><tbody>${metrics.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table><details style="margin-top:15px"><summary>원본 추가 지표 · 정의 · 수집 범위</summary><pre class="detail-json">${esc(JSON.stringify(p.extra,null,2))}</pre></details>`;document.getElementById('closeDetail').onclick=()=>document.getElementById('previewDialog').close();document.getElementById('previewDialog').showModal()}
function renderUpdates(){document.getElementById('body').innerHTML=`<div class="heading"><div><div class="eyebrow">DATA UPDATE</div><h1>업데이트 기록</h1><p class="subtitle">실제 데이터 전환 및 집계 기준</p></div><a class="btn" href="index.html">대시보드로 이동</a></div><section class="card timeline"><div class="release"><div><time>${DATA.asOfDate}</time><p><span class="tag">v2.0.0 · 실제 데이터</span></p></div><div><h2>가상 데이터 대신 실제 관찰값으로 교체</h2><ul><li>4개 계정, 26개 고유 콘텐츠의 실제 스냅샷 적용</li><li>난수 생성, 데모 팔로워, 가상 목표와 가상 달성률 제거</li><li>원본 보고 기간·수집 시각·데이터 없음 표시</li><li>YouTube·Facebook 일별 활동과 콘텐츠 누적값 분리</li><li>Instagram 공개 게시일 UTC를 확인해 KST 날짜로 변환</li><li>Facebook 공개 URL ID와 보고서 Page ID를 페이지 투명성에서 연결 확인</li><li>구매 전환으로 오해할 수 있는 전환수 열 제거</li><li>실제 썸네일이 확보된 콘텐츠만 원본 이미지 사용</li><li>미제공 일별값을 0으로 생성하지 않고 차트 간격 유지</li></ul></div></div></section><section class="card timeline"><h2 style="font-size:18px">수집과 해석</h2><p class="mini-note">최근 수집 ${kst(DATA.refreshedAt)} KST. 수동 관찰 스냅샷으로 자동 갱신되지 않습니다. 선택한 게시일 기간은 콘텐츠 누적 성과의 발생 기간이 아닙니다. 계정 조회수와 콘텐츠 누적 합계는 기간·범위·갱신 시점 때문에 다를 수 있습니다. 각 원자료 출처와 세부 지표는 대시보드의 원본 링크와 JSON/CSV로 확인할 수 있습니다.</p><p class="mini-note">${esc(DATA.facebookIdentity.note)} ${esc(DATA.dailyNotes.join(' '))}</p></section>`}
function boot(){const updates=location.pathname.endsWith('updates.html');document.getElementById('app').innerHTML=`<aside class="sidebar"><a class="brand" href="index.html"><span class="logo">∿</span><span>social pulse<span style="color:#8794ff">.</span></span></a><div class="worklabel">WORKSPACE</div><a class="nav ${updates?'':'active'}" href="index.html"><span class="navicon">▦</span><span>성과 대시보드</span></a><a class="nav ${updates?'active':''}" href="updates.html"><span class="navicon">◷</span><span>업데이트 기록</span></a><div class="worklabel">OBSERVED CHANNELS</div><div class="sidechannels">${CHANNELS.map(c=>`<div><i class="dot" style="background:${c.color}"></i>${c.name}</div>`).join('')}</div><div class="sidefoot"><span class="avatar">SP</span><div style="font-size:12px;color:#d5dce5">실제 계정 데이터<small>수동 수집 스냅샷</small></div></div></aside><main><div class="topbar"><span>워크스페이스 / ${updates?'업데이트 기록':'성과 대시보드'}</span><div class="topright"><span class="realbadge">REAL DATA</span><span class="status">기준 ${DATA.asOfDate} · 수집 ${kst(DATA.refreshedAt)} KST</span></div></div><div id="body"></div><footer class="footer"><span>Social Pulse · 원본 기간을 보존한 실제 관찰 데이터</span><span>자동 동기화 아님 · <a href="updates.html">v2.0.0</a></span></footer></main><dialog id="goalDialog"><form id="goalForm"><div class="eyebrow">WEEKLY PLANNING</div><h2>이번 주 목표 입력</h2><p class="mini-note">${thisWeek} ~ ${endWeek} · 직접 정한 목표만 저장합니다.<br>불완전한 실제 자료로 달성률이나 추천 목표를 만들지 않습니다.</p><label for="goalInput">합산 주간 조회수 목표 (회)</label><input id="goalInput" type="number" min="1" max="1000000000" step="1" required><div class="actions"><button class="btn" id="cancelGoal" type="button">취소</button><button class="btn primary">목표 저장</button></div><p class="mini-note" id="goalStatus"></p></form></dialog><dialog id="previewDialog" class="preview-dialog"><div id="detailBody"></div></dialog>`;if(updates)renderUpdates();else render();document.getElementById('cancelGoal').onclick=()=>document.getElementById('goalDialog').close();document.getElementById('goalForm').onsubmit=e=>{e.preventDefault();const v=Number(document.getElementById('goalInput').value);if(!Number.isInteger(v)||v<1||v>1e9)return;savedGoals[thisWeek]=v;try{localStorage.setItem('pulse-real-goals-v1',JSON.stringify(savedGoals));document.getElementById('goalDialog').close();if(!updates)render()}catch{document.getElementById('goalStatus').textContent='브라우저 저장소에 저장하지 못했습니다. 이 탭에서만 임시 적용됩니다.';if(!updates)render()}}}
boot();
